#!/usr/bin/env bash
set -euo pipefail

worker_environment_names='BAKERY_WORKER_SENTRY_DSN,BAKERY_SENTRY_ENABLED,BAKERY_SENTRY_ENVIRONMENT,BAKERY_SENTRY_RELEASE,BAKERY_SENTRY_TRACES_SAMPLE_RATE,HOME,PATH,DENO_DIR,TMPDIR,PI_CODING_AGENT_DIR,CODEX_HOME,BAKERY_ENV,BAKERY_SERVER_URL,BAKERY_VERSION,BAKERY_WORKER_STARTUP_MARKER,BAKERY_WORKER_NATIVE_SMOKE,BAKERY_WORKER_NATIVE_OUTPUT_FIXTURE,BAKERY_WORKER_CGROUP_ROOT,BAKERY_WORKER_ENROLLMENT_TOKEN_FILE,BAKERY_WORKER_ENROLLMENT_TOKEN_FD,BAKERY_WORKER_STATE_DIR,BAKERY_WORKER_NAME,BAKERY_WORKER_CAPABILITIES,BAKERY_WORKER_ADAPTER_CAPABILITIES,BAKERY_WORKER_TOOLCHAINS,BAKERY_WORKER_SLOTS,BAKERY_WORKER_HEARTBEAT_MS,BAKERY_WORKER_CLAIM_BACKOFF_MS,BAKERY_WORKER_CLAIM_BACKOFF_MAX_MS,BAKERY_WORKER_REQUEST_TIMEOUT_MS,BAKERY_WORKER_DRAIN_MS,BAKERY_WORKER_SPOOL_RECORDS,BAKERY_WORKER_SPOOL_BYTES,BAKERY_WORKER_OUTPUT_REDACTION_SECRETS,BAKERY_WORKER_LAUNCH_ID,BAKERY_WORKER_SCRIPTED_HARNESS_DIR,BAKERY_CLAUDE_AUTH_SOURCE_DIR,BAKERY_CODEX_AUTH_SOURCE_DIR,BAKERY_CLAUDE_COORDINATOR_TIME_LIMIT_MS,BAKERY_CLAUDE_COORDINATOR_EFFORT,BAKERY_CODEX_HARNESS,BAKERY_CODEX_HARNESS_REPOSITORY,BAKERY_CODEX_HARNESS_EXECUTABLE,BAKERY_CODEX_HARNESS_TIME_LIMIT_MS,BAKERY_CODEX_HARNESS_MODEL,BAKERY_CODEX_HARNESS_EFFORT,BAKERY_PI_HARNESS,BAKERY_PI_HARNESS_REPOSITORY,BAKERY_PI_HARNESS_EXECUTABLE,BAKERY_PI_HARNESS_TIME_LIMIT_MS,BAKERY_PI_HARNESS_MODEL,BAKERY_PI_HARNESS_EFFORT,BAKERY_CLAUDE_HARNESS,BAKERY_CLAUDE_HARNESS_REPOSITORY,BAKERY_CLAUDE_HARNESS_EXECUTABLE,BAKERY_CLAUDE_HARNESS_TIME_LIMIT_MS,BAKERY_CLAUDE_HARNESS_MODEL,BAKERY_CLAUDE_HARNESS_EFFORT'
mapfile -t worker_grants < <(
  deno run --no-prompt --allow-env="${worker_environment_names}" scripts/worker-permissions.ts
)
if [[ "${#worker_grants[@]}" -ne 5 || -z "${worker_grants[0]}" || -z "${worker_grants[1]}" || -z "${worker_grants[2]}" || -z "${worker_grants[3]}" || -z "${worker_grants[4]}" ]]; then
  echo "WORKER_LAUNCH_PERMISSIONS_INVALID" >&2
  exit 1
fi
exec deno run \
  --no-prompt \
  --preload=src/cgroup-permission-preload.ts \
  "--allow-env=${worker_environment_names}" \
  "--allow-read=${worker_grants[0]}" \
  "--allow-write=${worker_grants[1]}" \
  "--allow-net=${worker_grants[2]}" \
  "--allow-run=${worker_grants[3]}" \
  "--allow-sys=${worker_grants[4]}" \
  src/main.ts
